def sum_to(n):
    s = 0
    for i in range(1, n + 1):
        s += i
    return s

def digits_count(n):
    count = 0
    while n > 0:
        count += 1
        n //= 10
    return count

def collatz_steps(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

